import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import moment from 'moment-timezone'
import { Button, Menu, Dropdown, Icon, Row, Col, Input, Table } from 'antd'
import LayoutContent from '../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../components/utility/layoutWrapper'
import UmbrellaReportStyleWrapper from './gocar.style'
import gocarAction from '../../../redux/gocar/actions'
import XLSX from 'xlsx'
import downloader from '../../../../helpers/downloader'

const SEARCH_STORAGE_KEY = 'gocar_upload_list_search'

const { getUploadList } = gocarAction

class AgentTable extends PureComponent {
  constructor (props) {
    super(props)
    const savedSearch = localStorage.getItem(SEARCH_STORAGE_KEY) || ''
    this.state = {
      dataSource: [],
      filteredData: [],
      searchInput: savedSearch
    }
  }

  getColumns = () => {
    return [
      {
        title: 'Action',
        key: 'action',
        width: 110,
        render: (text, record) => (
          <i
            className='fa fa-eye'
            style={{ color: '#424242', fontSize: '18px', cursor: 'pointer' }}
            onClick={() => this.viewDetail(record.id, record)}
          />
        )
      },
      {
        title: 'Filename',
        dataIndex: 'original_filename',
        key: 'original_filename',
        width: 300,
        sorter: (a, b) => (a.original_filename || '').localeCompare(b.original_filename || '')
      },
      {
        title: 'Status',
        dataIndex: 'status',
        key: 'status',
        sorter: (a, b) => (a.status || '').localeCompare(b.status || '')
      },
      {
        title: 'Requested Payload',
        dataIndex: 'request_payload',
        key: 'request_payload',
        width: 300,
        sorter: (a, b) => (a.request_payload || '').localeCompare(b.request_payload || '')
      },
      {
        title: 'Notes',
        dataIndex: 'errors',
        key: 'errors',
        render: (text) => text === '[]' ? '' : text.slice(1, 20) + "..."
      },
      {
        title: 'Created at',
        dataIndex: 'created_at',
        key: 'created_at',
        width: 200,
        render: (text) => text ? moment(text).format('DD/MM/YYYY hh:mm:ss') : '',
        sorter: (a, b) => moment(a.created_at).unix() - moment(b.created_at).unix()
      },
      {
        title: 'Template Name',
        dataIndex: 'template_name',
        key: 'template_name',
        width: 300,
        sorter: (a, b) => (a.template_name || '').localeCompare(b.template_name || '')
      },
      {
        title: 'Uploaded By',
        dataIndex: 'user_name',
        key: 'user_name',
        sorter: (a, b) => (a.user_name || '').localeCompare(b.user_name || '')
      },
      {
        title: 'File url',
        dataIndex: 'file_url',
        key: 'file_url',
        width: 600,
        render: (text) => text ? <a href={text} target='_blank' rel='noopener noreferrer'>{text}</a> : ''
      }
    ]
  }

  applySearch = (data, searchValue) => {
    if (!searchValue) return data
    const searchLower = searchValue.toLowerCase()
    return data.filter(record =>
      Object.values(record).some(val =>
        val && val.toString().toLowerCase().includes(searchLower)
      )
    )
  }

  viewDetail = (id, data) => {
    this.props.history.push(`/gocar/upload-list/${id}`, { params: { data } })
  }

  componentWillReceiveProps (nextProps) {
    const { data, status } = nextProps.gocarData
    const uploadData = (data && status === 'success') ? data : []
    this.setState({
      dataSource: uploadData,
      filteredData: this.applySearch(uploadData, this.state.searchInput)
    })
  }

  componentDidMount () {
    this.props.getUploadList()
  }

  dateGenerator = () => {
    let today = new Date()
    let dd = today.getDate()
    let mm = today.getMonth() + 1 // January is 0!
    let yyyy = today.getFullYear()
    if (dd < 10) dd = '0' + dd
    if (mm < 10) mm = '0' + mm
    let assignment = today = mm + '-' + dd + '-' + yyyy
    return assignment
  }

  exportToExcel () {
    const { filteredData } = this.state
    const exportData = filteredData.map(row => ({
      'Filename': row.original_filename || '',
      'Status': row.status || '',
      'Errors': row.errors === '[]' ? '' : (row.errors || '')
    }))

    const worksheet = XLSX.utils.json_to_sheet(exportData)
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Upload Data')
    const xlsxContent = XLSX.write(workbook, { bookType: 'xlsx', type: 'base64' })
    const params = {
      fileName: 'excel_uploaded_data' + this.dateGenerator()
    }
    downloader(params, xlsxContent)
  }

  onClearFilter = () => {
    localStorage.removeItem(SEARCH_STORAGE_KEY)
    this.setState({
      searchInput: '',
      filteredData: this.state.dataSource
    })
  }

  onFilterChange = (val) => {
    const searchValue = val.target.value
    localStorage.setItem(SEARCH_STORAGE_KEY, searchValue)
    this.setState({
      searchInput: searchValue,
      filteredData: this.applySearch(this.state.dataSource, searchValue)
    })
  }

  render () {
    const { filteredData, searchInput } = this.state
    const menu = (
      <Menu onClick={this.exportToExcel.bind(this)}>
        <Menu.Item key='1'><Icon type='right-circle-o' /> Excel</Menu.Item>
      </Menu>
    )
    return (
      <UmbrellaReportStyleWrapper>
        <LayoutContentWrapper className='referral-table' style={{ minHeight: '90vh' }}>
          <LayoutContent style={{ padding: '6vh' }}>
            <Row gutter={16}>
              <Col className='gutter-row-export-csv' span={24} style={{ display: 'flex', justifyContent: 'space-between' }}>
                <h3>Upload list</h3>
                <div style={{ display: 'flex' }}>
                  <Button style={{ marginRight: '10px' }} onClick={this.onClearFilter}><Icon type='filter' /> Clear filters</Button>
                  <Input value={searchInput} type='text' id='filter-text-box' placeholder='Search...' onInput={val => this.onFilterChange(val)} style={{ width: '200px', borderRadius: '0px', marginRight: '10px' }} />
                  <Dropdown overlay={menu}>
                    <Button>Export to <Icon type='down' /></Button>
                  </Dropdown>
                </div>
              </Col>
            </Row>
            <Table
                columns={this.getColumns()}
                dataSource={filteredData}
                rowKey={(record) => record.id || Math.random()}
                pagination={{
                  pageSize: 10,
                  showSizeChanger: true,
                  showQuickJumper: true,
                  showTotal: (total, range) => `[${range[0]}-${range[1]}] of ${total} items`
                }}
                locale={{
                  emptyText: 'Data is empty / failed to fetch :('
                }}
                scroll={{ x: true, y: true }}
                style={{ marginTop: '16px' }}
              />
          </LayoutContent>
        </LayoutContentWrapper>
      </UmbrellaReportStyleWrapper>
    )
  }
}

export default connect(
  state => ({
    gocarData: state.Gocar
  }),
  { getUploadList }
)(AgentTable)
